// OpenRouterIcon.h -- auto-generated 1-bit PROGMEM mask, 32x32.
// Source: the OpenRouter brand mark PNG the user supplied directly (purple
// "OR" glyph -- a rounded pill body with a circular hole on the left and a
// pointed tail on the right, on a near-white background). Same conversion
// method as AntigravityIcon.h/ZaiIcon.h/CodexIcon.h: alpha/near-white
// threshold to a binary ink mask, cropped to the true ink bounding box
// (206x145 of the 384x384 source), then ONE uniform NEAREST scale factor on
// both axes (not stretched), centered both horizontally and vertically
// inside the unchanged 32x32 canvas.
//
// Went through two sizes live: first a 20x14 footprint (small, real margin
// on all sides) after a full-canvas-filling attempt was rejected ("not even
// close" / "the one u made is cropped u gotta zoom out more the logo doesnt
// have to be large") -- at full-canvas scale the hole/tail lost proportion
// and stopped reading as the logo. Once the header text moved to size2
// ("openrouter" was overlapping the clock overlay at size3), there was
// headroom to grow it back: current is a 28x20 footprint (offset 2,6) --
// "and logo can be larger if we have space" -- same crop, same uniform
// scale-both-axes method, just a bigger target size. Verified via an ASCII
// dump and a 16x upscaled preview PNG before committing either time.
#pragma once
#include <Arduino.h>

